'use strict';

function plain(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function computeStripView(items, start, visibleCount, action) {
  if (!Array.isArray(items) || items.some((item) => !plain(item))) throw new TypeError('invalid items');
  if (!Number.isInteger(start) || start < 0) throw new TypeError('invalid start');
  if (!Number.isInteger(visibleCount) || visibleCount <= 0) throw new TypeError('invalid visibleCount');
  if (!['stay', 'left', 'right', 'advance'].includes(action)) throw new TypeError('invalid action');

  const maxStart = Math.max(0, items.length - visibleCount);
  let next = Math.min(start, maxStart);
  if (action === 'left') next = Math.max(0, next - 1);
  if (action === 'right') next = next + 1;
  if (action === 'advance') next = next >= maxStart ? 0 : next + 1;

  return {
    start: next,
    visibleItems: items.slice(next, next + visibleCount).map((item) => ({ ...item })),
    canLeft: next > 0,
    canRight: next < maxStart
  };
}

module.exports = { computeStripView };

