'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['computeStripView']);
const { computeStripView } = api;
const typeError = fn => assert.throws(fn, TypeError);

const items = [{ id: 1 }, { id: 2 }, { id: 3 }, { id: 4 }];
const snapshot = JSON.parse(JSON.stringify(items));
assert.deepStrictEqual(computeStripView(items, 0, 2, 'stay'), { start: 0, visibleItems: [{ id: 1 }, { id: 2 }], canLeft: false, canRight: true });
assert.deepStrictEqual(computeStripView(items, 0, 2, 'right'), { start: 1, visibleItems: [{ id: 2 }, { id: 3 }], canLeft: true, canRight: true });
assert.deepStrictEqual(computeStripView(items, 2, 2, 'right'), { start: 2, visibleItems: [{ id: 3 }, { id: 4 }], canLeft: true, canRight: false });
assert.deepStrictEqual(computeStripView(items, 9, 2, 'left'), { start: 1, visibleItems: [{ id: 2 }, { id: 3 }], canLeft: true, canRight: true });
assert.deepStrictEqual(computeStripView(items, 2, 2, 'advance'), { start: 0, visibleItems: [{ id: 1 }, { id: 2 }], canLeft: false, canRight: true });
assert.deepStrictEqual(computeStripView(items, 0, 10, 'advance'), { start: 0, visibleItems: [{ id: 1 }, { id: 2 }, { id: 3 }, { id: 4 }], canLeft: false, canRight: false });
for (const action of ['stay', 'left', 'right', 'advance']) {
  assert.deepStrictEqual(computeStripView([], 100, 3, action), { start: 0, visibleItems: [], canLeft: false, canRight: false });
}
const view = computeStripView(items, 0, 1, 'stay');
assert.notStrictEqual(view.visibleItems[0], items[0]);
view.visibleItems[0].id = 99;
assert.deepStrictEqual(items, snapshot);

typeError(() => computeStripView({}, 0, 1, 'stay'));
typeError(() => computeStripView([null], 0, 1, 'stay'));
typeError(() => computeStripView(items, -1, 1, 'stay'));
typeError(() => computeStripView(items, 1.5, 1, 'stay'));
typeError(() => computeStripView(items, 0, 0, 'stay'));
typeError(() => computeStripView(items, 0, 1.2, 'stay'));
typeError(() => computeStripView(items, 0, 1, 'up'));

